const strip=document.querySelector("#era-strip"),detail=document.querySelector("#era-detail");const escapeHTML=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const dateLabel=date=>{if(date.precision==="undated")return"Sin datación histórica verificable";if(date.precision==="debated")return"Cronología debatida";const fmt=n=>n==null?"actualidad":n<0?`${Math.abs(n)} a. C.`:`${n} d. C.`;return `${date.precision==="approximate"?"c. ":""}${fmt(date.startYear)} – ${fmt(date.endYear)}`};const yearLabel=date=>date.year==null?"Fecha no fijada":`${date.precision==="approximate"?"c. ":""}${date.year<0?Math.abs(date.year)+" a. C.":date.year+" d. C."}`;async function init(){try{const response=await fetch(new URL("./data/history/timeline.json",import.meta.url));if(!response.ok)throw Error("No se pudo cargar la cronología");const data=await response.json();if(!Array.isArray(data.eras)||!Array.isArray(data.events))throw Error("Formato de cronología inválido");const eras=[...data.eras].sort((a,b)=>a.order-b.order);let active=new URL(location.href).searchParams.get("era");if(!eras.some(e=>e.id===active))active=eras[0].id;const select=id=>{active=id;strip.innerHTML=eras.map(era=>`<button type="button" class="era-tab ${era.id===active?"selected":""}" data-era="${escapeHTML(era.id)}" style="--era-color:${escapeHTML(era.color)}" aria-pressed="${era.id===active}"><span class="swatch"></span><strong>${escapeHTML(era.title)}</strong><small>${escapeHTML(dateLabel(era.date))}</small></button>`).join("");const era=eras.find(e=>e.id===id);const events=data.events.filter(event=>event.eraId===id).sort((a,b)=>a.order-b.order);detail.style.setProperty("--era-color",era.color);detail.innerHTML=`<div class="era-heading"><span class="era-kicker">${escapeHTML(era.subtitle)}</span><h3>${escapeHTML(era.title)}</h3><p class="era-date">${escapeHTML(dateLabel(era.date))}</p></div><p class="era-summary">${escapeHTML(era.summary)}</p><h4>Acontecimientos</h4><ol class="event-list">${events.map(event=>`<li><span class="event-title">${escapeHTML(event.title)}</span>${event.date.year!=null?`<small>${escapeHTML(yearLabel(event.date))}</small>`:""}</li>`).join("")}</ol><h4>Libros relacionados</h4><div class="book-chips">${era.bookIds.length?era.bookIds.map(book=>`<span>${escapeHTML(book.replace(/-/g," "))}</span>`).join(""):"<span>Contexto histórico extrabíblico</span>"}</div>`;const u=new URL(location.href);u.searchParams.set("era",id);history.replaceState(null,"",u);};strip.addEventListener("click",event=>{const button=event.target.closest("[data-era]");if(button)select(button.dataset.era)});select(active)}catch(error){detail.innerHTML=`<p role="alert">No pudimos cargar la cronología. <button onclick="location.reload()">Reintentar</button></p>`;console.error(error)}}init();